from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.db_stats.bts.bts_stats import BTSStats


class BTSKPIStats(BTSStats):
    _kpi_cell_db_marker = "DB->decimal properties->device:{device_name}->cell:{cell}->KPI id:{kpi_id}->BTS KPI"
    _kpi_db_marker = "DB->decimal properties->device:{device_name}->KPI id:{kpi_id}->BTS KPI"

    def __call__(self):
        for path_to_json_file in self.get_all_results_file_locations(json_file='result.json'):
            device_name = self.get_device_name_from_pmstats_path(path_to_json_file)
            kpi = self.load_stats_file(path_to_json_file)
            self.add_stats_for_particular_device(data=kpi, device_name=device_name)

    def add_stats_for_particular_device(self, data, device_name):
        device_stats = {}
        for kpi_id in data:
            marker_params = {
                'device_name': device_name,
                'kpi_id': kpi_id
            }

            for stats_object in data[kpi_id]:
                value = data[kpi_id][stats_object]['Average']
                if value == 'NA':
                    continue
                if stats_object == 'BTS':
                    marker = BTSKPIStats._kpi_db_marker.format(**marker_params)
                else:
                    marker_params['cell'] = stats_object
                    marker = BTSKPIStats._kpi_cell_db_marker.format(**marker_params)

                device_stats[marker] = value

                marker_params.pop('cell', None)

        tc.add_stats(stats=device_stats)
